<template><div class="page"><div class="page-header"><h2>通知记录</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="template_id" label="模板ID" width="100"/><el-table-column prop="recipient" label="接收方" width="140"/><el-table-column label="渠道" width="70"><template #default="{row}"><el-tag size="small">{{ row.channel }}</el-tag></template></el-table-column><el-table-column prop="ref_type" label="关联类型" width="100"/><el-table-column prop="ref_id" label="关联ID" width="100"/><el-table-column label="发送状态" width="80"><template #default="{row}"><el-tag :type="sendStatusTag(row.send_status)" size="small">{{ row.send_status||'pending' }}</el-tag></template></el-table-column><el-table-column prop="send_time" label="发送时间" width="110"/></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'通知详情'" v-model="drawer" width="600px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="模板ID">{{ detail.template_id||'-' }}</el-descriptions-item><el-descriptions-item label="渠道">{{ detail.channel }}</el-descriptions-item><el-descriptions-item label="接收方">{{ detail.recipient }}</el-descriptions-item><el-descriptions-item label="发送状态"><el-tag :type="sendStatusTag(detail.send_status)" size="small">{{ detail.send_status||'pending' }}</el-tag></el-descriptions-item><el-descriptions-item label="关联类型">{{ detail.ref_type||'-' }}</el-descriptions-item><el-descriptions-item label="关联ID">{{ detail.ref_id||'-' }}</el-descriptions-item><el-descriptions-item label="发送时间">{{ detail.send_time||'-' }}</el-descriptions-item><el-descriptions-item label="错误信息" :span="2">{{ detail.error_msg||'无' }}</el-descriptions-item></el-descriptions><div style="margin-top:12px"><strong>标题:</strong><p style="margin-top:4px;color:#303133">{{ detail.subject||'-' }}</p></div><div style="margin-top:12px"><strong>正文:</strong><pre style="background:#f5f7fa;padding:12px;border-radius:4px;margin-top:8px;white-space:pre-wrap;font-size:13px">{{ detail.body||'-' }}</pre></div></template></el-dialog></div></template>
<script setup lang="ts">import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {fetchNotifications} from '@/api/notification';import type {NotifRecord} from '@/api/notification'
const{items,loading,page,perPage,total}=useListPage<NotifRecord>(fetchNotifications);const{drawer,detail,open}=useDetailDrawer<NotifRecord>()
function sendStatusTag(s:string){const m:Record<string,string>={pending:'info',sent:'success',failed:'danger'};return m[s]||'info'}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}</style>
